(() => {
  const {money,escapeHtml:e,vehicleTitle,estimate} = DF;
  const root = document.querySelector('#vehicle-content');
  const id = new URLSearchParams(location.search).get('id');
  fetch('vehicles.json').then(response => {if(!response.ok)throw new Error();return response.json();}).then(data => {
    const car = data.vehicles.find(item => String(item.id) === id);
    if (!car) {root.innerHTML = '<div class="page-message"><h1>Let’s find your next drive.</h1><p>This vehicle could not be found in the current collection.</p><a class="button button-black" href="index.html#showroom">Back to the showroom <span>↗</span></a></div>';return;}
    document.title = `${car.year} ${vehicleTitle(car)} | Driving Force`;
    root.innerHTML = `<a class="back-link" href="index.html#showroom">← Back to the showroom</a>
      <div class="vehicle-page-heading"><div><p>${car.year} · ${e(car.body_type)}</p><h1>${e(vehicleTitle(car))}</h1><p class="detail-variant">${e(car.variant)}</p></div><div class="detail-price-block"><strong class="detail-price">${money(car.value)}</strong><a class="button button-black" href="visit.html?vehicle=${car.id}">Visit the showroom <span>↗</span></a></div></div>
      <div class="vehicle-layout"><article class="vehicle-story"><img class="detail-photo" src="${e(car.localImage)}" alt="${e(car.year+' '+vehicleTitle(car))}" width="800" height="533"><dl class="detail-specs">${[['Mileage',Number(car.mile).toLocaleString('en-ZA')+' km'],['Transmission',car.transmission],['Fuel',car.fuelType],['Colour',car.colour],['Body',car.body_type],['Stock reference',car.stock_code]].map(([label,value])=>`<div><dt>${label}</dt><dd>${e(value)}</dd></div>`).join('')}</dl><div class="vehicle-visit"><h2>See it for yourself.</h2><p>Visit us at 21 Montague Drive, Montague Gardens, Cape Town. Our team can confirm availability and arrange a viewing.</p><div class="vehicle-visit-actions"><a class="button button-black" href="visit.html?vehicle=${car.id}">Visit the showroom <span>↗</span></a><a class="phone-link" href="tel:+27212038888">Call 021 203 8888</a></div></div><p class="stock-note">Vehicle information captured ${e(data.retrieved)}. Confirm availability with our team.</p></article>
      <aside class="vehicle-finance" aria-labelledby="estimate-title"><h2 id="estimate-title">Make it yours.</h2><p class="form-intro">Explore a monthly payment for this ${e(vehicleTitle(car))}.</p><form id="vehicle-estimate" class="estimate-form"><div class="form-grid"><label>Vehicle price<div class="line-input"><span>R</span><input name="price" type="number" readonly value="${car.value}" min="1" max="10000000" step="any" required inputmode="decimal"></div></label><label>Deposit<div class="line-input"><span>R</span><input name="deposit" type="number" value="0" min="0" step="any" required inputmode="decimal"></div></label><label>Net trade-in value<div class="line-input"><span>R</span><input name="tradeIn" type="number" value="0" min="0" step="any" required inputmode="decimal"></div></label><label>Annual interest rate<div class="line-input"><input name="rate" type="number" value="12" min="0" max="30" step="any" required inputmode="decimal"><span>%</span></div></label><label class="span-two">Repayment term<select name="term">${[6,12,18,24,30,36,42,48,54,60,66,72,78,84,90,96].map(term=>`<option value="${term}" ${term===72?'selected':''}>${term} months</option>`).join('')}</select></label></div><p id="estimate-error" class="form-error" role="status"></p><div class="estimate-result" aria-live="polite"><span>Estimated monthly payment</span><p><strong id="estimate-monthly">—</strong><span> / month</span></p></div><a class="button button-red full-width" href="finance.html?vehicle=${car.id}" id="apply-finance">Apply for finance <span>↗</span></a><dl class="estimate-totals"><div><dt>Amount financed</dt><dd id="estimate-principal">—</dd></div><div><dt>Total interest</dt><dd id="estimate-interest">—</dd></div><div><dt>Total loan repayments</dt><dd id="estimate-total">—</dd></div></dl><p class="estimate-note">Illustrative estimate, subject to lender approval. Excludes fees, insurance and balloon payments. Net trade-in value is the amount available after settling any existing vehicle loan.</p><p class="estimate-note">Complete the full application here on our website.</p></form></aside></div>`;
    const form = document.querySelector('#vehicle-estimate');
    form.addEventListener('submit',event=>event.preventDefault());
    function calculate() {
      const values = Object.fromEntries([...new FormData(form)].map(([name,value])=>[name,value === '' ? NaN : Number(value)]));
      const result = form.checkValidity() ? estimate(values) : null;
      document.querySelector('#estimate-error').textContent = result ? '' : 'Enter valid amounts. Deposit and net trade-in together cannot exceed the vehicle price.';
      for(const key of ['monthly','principal','interest','total']) document.querySelector('#estimate-'+key).textContent = result ? money(result[key]) : '—';
      // Only non-personal vehicle and estimate values are passed to the application.
      const params = new URLSearchParams({vehicle:car.id});
      if(result) for(const key of ['deposit','tradeIn','rate','term']) params.set(key,values[key]);
      document.querySelector('#apply-finance').href = 'finance.html?'+params;
    }
    form.addEventListener('input',calculate);calculate();
  }).catch(()=>{root.innerHTML='<div class="page-message"><h1>The vehicle could not load.</h1><p>Please try again or contact our showroom.</p><a class="button button-black" href="index.html#showroom">Back to the showroom</a></div>';});
})();
